                checkpoint_hash = self._resource_checkpoint(proposal_id, logical_id, attempt_id, bindings, checkpoint, start_ns, ctx)
                return {"status": "RESOURCE_EXHAUSTED_OWNER_ACTION_REQUIRED", "proposal_id": proposal_id, "logical_trial_id": logical_id, "attempt_id": attempt_id, "checkpoint_sha256": checkpoint_hash}
            candidate_id = order[index]
            candidate = candidates_by_id[candidate_id]
            # F07: rejection states were frozen pre-marker; a rejected candidate
            # produces no scientific output and never aborts the wave.
            reason = rejection_by_candidate[candidate_id]
            if reason:
                diagnostics.append({"candidate_id": candidate_id, "rejected": reason})
                continue
            horizon = int(candidate["holding_horizon_hours"])
            admissible = admissible_by_horizon[horizon]
            # F03: each candidate consumes exactly its horizon's label stream.
            labels_h = labels_by_horizon.get(str(horizon))
            if labels_h is None:
                raise FailClosed("W1_HORIZON_LABEL_STREAM_MISSING")
            allowed_end_us = allowed_by_horizon.get(str(horizon), -1)
            label_end_us = label_end_by_horizon.get(str(horizon), -1)
            frozen_rows = [frozen[candidate_id][item] for item in admissible]
            turnover_series = mat.turnover_series_for_frozen(frozen_rows)
            components = []
            estimator_totals: list[np.float64] = []
            estimator_turnovers: list[np.float64] = []
            long_values: list[np.float64] = []
            short_values: list[np.float64] = []
            for position, cohort_index in enumerate(admissible):
                frozen_row = frozen_rows[position]
                if frozen_row.get("state") != "FROZEN":
                    components.append({"state": "STRUCTURALLY_UNDEFINED"})
                    continue
                label_row = labels_h[cohort_index]
                if label_row is None:
                    raise FailClosed("W1_LABEL_COHORT_MISSING")
                gate = evaluator.LabelGate(label_row, allowed_end_us)
                gate.open(frozen_row, True, label_end_us)
                component = evaluator.evaluate_frozen_portfolio(frozen_row, gate)
                components.append(component)
                if component.get("state") == "OUTCOME_COMPLETE":
                    # F02: estimator sample is exactly the complete cohorts.
                    estimator_totals.append(np.float64(component["TOTAL"]))
                    long_r, short_r = self._leg_contributions(frozen_row, gate)
                    long_values.append(long_r)
                    short_values.append(short_r)
                    if horizon == 8:
                        estimator_turnovers.append(np.float64(turnover_series[position]))
