            if series.size == 0:
                raise FailClosed("W1_ESTIMATOR_EMPTY")
            long_leg = np.asarray(long_values, dtype=np.float64)
            short_leg = np.asarray(short_values, dtype=np.float64)
            if horizon == 8:
                # F05: prereg V3 section 12 turnover incl. entry/exit notionals.
                traded = [value for value in turnover_series if value is not None]
                turnover_arg = np.float64(np.mean(np.asarray(traded, dtype=np.float64),
                                                  dtype=np.float64))
                net_value = mat.net_fee_only_mean(estimator_totals, estimator_turnovers)
                net_semantics = "GROSS_MINUS_FEE_NET_MEAN_PREREG_V3_S12"
            else:
