                net_value = "UNAVAILABLE"
                net_semantics = "NET_UNAVAILABLE_OVERLAP_CONTRACT_S3"
            stats = evaluator.hac_mean(series, horizon)
            sign = mat.predicted_sign_prior(candidate)
            source_alignment = None
            if sign is not None and np.isfinite(stats["construction_t"]):
                # F06: SOURCE_ALIGNMENT_T = PREDICTED_SIGN_PRIOR * CONSTRUCTION_T.
                source_alignment = np.float64(sign) * np.float64(stats["construction_t"])
