                candidate, series, long_leg, short_leg, components,
                turnover_arg, source_alignment)
            diagnostic["net_fee_only_mean"] = net_value
            diagnostic["net_fee_only_semantics"] = net_semantics
            diagnostic["turnover_series_admissible"] = [
                None if value is None else float(value) for value in turnover_series]
            diagnostic["admissible_cohorts"] = len(admissible)
