        risc = evaluator.risc_record(str(bindings.wave_id), str(bindings.candidate_list_sha256), 174, 174, 174, rejected)
        sealed_payload = {"schema": "p5-wave1-sealed-result/v2", "proposal_id": proposal_id, "binding_sha256": bindings.digest, "evaluator_sha256": bindings.evaluator_sha256, "materializer_sha256": mat.materializer_sha256(), "rejection_set_sha256": rejection_set_sha256, "candidate_count": 174, "diagnostics": diagnostics, "risc": risc}
        sealed = self._complete_seal(proposal_id, logical_id, attempt_id, kind, bindings, sealed_payload, None, start_ns, ctx)
        return {"status": "SEALED", "proposal_id": proposal_id, "logical_trial_id": logical_id, "attempt_id": attempt_id, "attempt_ordinal": ordinal, "sealed_artifact_sha256": sealed}

    def trial_status(self, proposal_id: str) -> dict[str, Any]:
        con = self._open()
        try:
            logical = con.execute("SELECT logical_trial_id FROM logical_trials WHERE grant_proposal_id=?", (proposal_id,)).fetchone()
            if not logical:
                return {"status": "NOT_STARTED", "proposal_id": proposal_id}
            seal = con.execute("SELECT result_sha256,result_kind,result_state FROM sealed_results WHERE proposal_id=?", (proposal_id,)).fetchone()
            attempts = int(con.execute("SELECT count(*) FROM trial_attempts WHERE logical_trial_id=?", (logical[0],)).fetchone()[0])
            if seal:
                result = {"status": "SEALED", "proposal_id": proposal_id, "logical_trial_id": logical[0], "attempt_count": attempts, "sealed_artifact_sha256": seal[0]}
                if seal[1] == "T1":
                    result["result_state"] = seal[2]
                return result
            return {"status": "IN_PROGRESS_OR_ACTION_REQUIRED", "proposal_id": proposal_id, "logical_trial_id": logical[0], "attempt_count": attempts}
        finally:
            con.close()


def _json_safe(value: Any) -> Any:
    if isinstance(value, dict):
        return {str(key): _json_safe(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_json_safe(item) for item in value]
    if isinstance(value, np.generic):
        return value.item()
    return value


def verify_execution_integrity(con: apsw.Connection, artifact_root: Path) -> dict[str, Any]:
    required = {"precondition_evidence", "trial_attempt_events", "label_access_ledger", "wave_resource_events", "sealed_results"}
    present = {row[0] for row in con.execute("SELECT name FROM sqlite_schema WHERE type='table'")}
    if not required <= present:
        return {"status": "FAIL", "errors": ["ALPHA_EXECUTION_SCHEMA_INCOMPLETE"], "missing_tables": sorted(required - present)}
    errors: list[str] = []
    for evidence_sha, evidence_json, proposal_id, transition_id in con.execute("SELECT evidence_sha256,evidence_json,proposal_id,preconditions_transition_id FROM precondition_evidence"):
        if _sha_bytes(evidence_json.encode("utf-8")) != evidence_sha:
            errors.append(f"PRECONDITION_EVIDENCE_HASH:{proposal_id}")
        row = con.execute("SELECT proposal_id,to_state FROM authority_transitions WHERE transition_id=?", (transition_id,)).fetchone()
        if row != (proposal_id, "PRECONDITIONS_PASS"):
            errors.append(f"PRECONDITION_EVIDENCE_POINTER:{proposal_id}")
    pointers = set()
    for result_sha, relpath, size, proposal_id in con.execute("SELECT result_sha256,artifact_relpath,artifact_size,proposal_id FROM sealed_results"):
        try:
            path = _safe_child(Path(artifact_root), relpath, "SEALED_RESULT_PATH_INVALID")
            pointers.add(path.resolve())
            if not path.is_file() or path.stat().st_size != size or _file_sha256(path) != result_sha:
                errors.append(f"SEALED_RESULT_ARTIFACT:{proposal_id}")
        except FailClosed:
            errors.append(f"SEALED_RESULT_PATH:{proposal_id}")
    for logical_id, kind, t1_sha in con.execute("SELECT logical_trial_id,access_kind,t1_seal_sha256 FROM label_access_ledger"):
        if kind == "W1":
            t1 = con.execute("SELECT result_state FROM sealed_results WHERE result_sha256=? AND result_kind='T1'", (t1_sha,)).fetchone()
            if not t1 or t1[0] == "TEST_VOIDED":
                errors.append(f"W1_T1_FIRST:{logical_id}")
    orphan_count = 0
    result_dir = Path(artifact_root) / "results"
    if result_dir.is_dir():
        orphan_count = sum(1 for path in result_dir.glob("*.json") if path.resolve() not in pointers)
    return {"status": "PASS" if not errors else "FAIL", "errors": errors, "sealed_result_count": len(pointers), "orphan_artifact_count": orphan_count, "orphan_standing": "ZERO"}

